<script setup>
import {ref,onMounted} from 'vue'
import {api,notify,run,rememberGreeting,date} from '../lib'
const form=ref({scene:'生日祝福',receiver:'',style:'温柔浪漫',extra:''}),content=ref(localStorage.getItem('orderGreeting')||''),source=ref(''),busy=ref(false),history=ref({items:[],total:0}),page=ref(1)
const scenes=['生日祝福','情人节表白','母亲节祝福','毕业祝福','开业祝福','感谢祝福','节日祝福'],styles=['温柔浪漫','简约高级','幽默有趣','真诚感人','文艺清新']
async function load(){history.value=await api.get('/ai/greeting/list',{params:{page:page.value}})}
async function generate(){if(busy.value)return;busy.value=true;try{let r=await api.post('/ai/greeting/generate',form.value);content.value=r.content;source.value=r.source;await load()}finally{busy.value=false}}
async function copy(){await navigator.clipboard.writeText(content.value);notify('祝福语已复制')}
onMounted(()=>run(load))
</script>
<template><section class="page-intro wrap"><span class="eyebrow">A LITTLE HELP TO SAY IT RIGHT</span><h1>让心意，落在字里行间。</h1><p>选好花，再写一张只属于 TA 的花卡。</p></section><section class="greeting-layout wrap section"><form class="panel greeting-form" @submit.prevent="run(generate)"><div class="panel-title"><Icon name="spark"/><h3>定制你的专属祝福</h3></div><label>在什么时刻送出？</label><div class="filter-chips"><button type="button" v-for="x in scenes" :key="x" :class="{active:form.scene===x}" @click="form.scene=x">{{x}}</button></div><label>想送给谁？<input v-model="form.receiver" required maxlength="50" placeholder="例如：妈妈 / 好朋友小林 / 爱人"/></label><label>希望是什么语气？<select v-model="form.style"><option v-for="x in styles" :key="x">{{x}}</option></select></label><label>再多告诉我们一点 <span class="subtle">（选填）</span><textarea v-model="form.extra" maxlength="300" rows="3" placeholder="例如：相识第三年，感谢你一直陪伴着我。"/></label><button class="btn primary" :disabled="busy"><Icon name="spark" :size="18"/> {{busy?'正在写下心意…':content?'再生成一份祝福':'生成一份祝福'}}</button><p class="subtle">无密钥时使用本地模板；已配置 AI 服务时，由后端安全调用。</p></form><div class="greeting-preview"><div class="paper-card"><span class="eyebrow">A NOTE FOR YOU</span><Icon name="flower" :size="34"/><h2>字短情长，见字如面。</h2><textarea v-model="content" maxlength="1000" placeholder="你的专属祝福，将在这里绽放。\n生成后也可以自由修改。" aria-label="编辑祝福语"/><span class="signature">With love, FLEUR</span><small v-if="source">{{source==='AI'?'AI 生成 · 请核对后使用':'本地模板生成 · 尚未调用AI服务'}}</small></div><div class="greeting-actions"><button class="btn" :disabled="!content" @click="run(copy)">复制祝福</button><button class="btn primary" :disabled="!content" @click="rememberGreeting(content)">保存并用于订单 <Icon name="arrow" :size="16"/></button></div></div></section><section class="wrap section"><div class="section-heading"><h2>写过的心意</h2><span class="subtle">每次生成自动保存，订单采用你最后编辑的文字。</span></div><div class="history-grid"><article class="panel" v-for="g in history.items" :key="g.id"><span class="eyebrow">{{g.scene}} · {{g.source==='AI'?'AI':'本地模板'}}</span><h3>To. {{g.receiver}}</h3><p>{{g.content}}</p><div class="row-between"><small>{{date(g.create_time)}}</small><div><button class="text-button" @click="content=g.content;source=g.source;rememberGreeting(g.content)">使用</button><button class="text-button muted" @click="run(async()=>{await api.delete('/ai/greeting/'+g.id);await load()})">删除</button></div></div></article></div><div class="empty" v-if="!history.total">还没有祝福记录，写下第一份心意吧。</div><Pager :page="page" :total="history.total" @change="v=>{page=v;run(load)}"/></section></template>
